// Email intake adapter. Accepts a Gmail Trigger item (simplified or raw) or an
// Email Trigger (IMAP) item and emits { source, raw_message } at the root -
// exactly the shape Prepare Input already falls back to, so the API path and the
// email path converge on one validated pipeline instead of two.

const j = $json;

const stripHtml = (html) => String(html)
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'");

// Gmail Trigger        -> From / Subject / text / html
// Email Trigger (IMAP) -> from / subject / textPlain / textHtml
const subject = (j.Subject ?? j.subject ?? '').toString().trim();
const from = (
  j.From ??
  (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) ??
  (j.from && j.from.text) ??
  j.from ??
  ''
).toString().trim();

const plain = j.text ?? j.textPlain ?? '';
const html = j.html ?? j.textHtml ?? '';
let body = (plain || (html ? stripHtml(html) : '') || j.snippet || '').toString();

// Drop quoted reply history and the signature block: on a long thread the
// classifier would otherwise triage the oldest message rather than this reply.
body = body
  .replace(/\r\n/g, '\n')
  .split(/^\s*(?:On .+wrote:|-{2,}\s*Original Message\s*-{2,}|_{10,})\s*$/m)[0]
  .split(/\n--\s*\n/)[0]
  .split('\n')
  .map((line) => line.trim())
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// The subject line carries real triage signal ("URGENT: dashboard down"), so it
// is classified text rather than metadata. Prepare Input applies the 8 000
// character cap, so that limit stays defined in exactly one place.
const raw_message = [subject ? 'Subject: ' + subject : '', body]
  .filter(Boolean)
  .join('\n\n');

// Machine mail must never reach the classifier: it burns tokens and writes
// triage records no human ever sent. Acted on by the next node.
const is_automated =
  /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounce[s]?@)/i.test(from) ||
  /^\s*(out of office|automatic reply|auto[- ]reply|undeliverable|delivery status notification)/i.test(subject);

// 'Email' belongs to this path alone. The web form offers only 'Web Form' and
// 'Support Portal', so this label always means a message that genuinely arrived
// in the mailbox rather than one pasted into the form.
return [{
  json: {
    source: 'Email',
    raw_message,
    from,
    subject,
    message_id: (j.id ?? j.messageId ?? '').toString(),
    thread_id: (j.threadId ?? '').toString(),
    is_automated,
  },
}];

const orig = $('Prepare Input').item.json;

// Unwrap the json_schema output from the Classify node.
const rawText = $json.output && $json.output[0] && $json.output[0].content && $json.output[0].content[0]
  ? $json.output[0].content[0].text
  : undefined;

let parsed = rawText;
if (typeof parsed === 'string') {
  // Throw rather than swallow. A silent {} fallback would store a fake record that
  // looks like a genuine low-confidence triage; the error output returns 502 instead.
  parsed = JSON.parse(parsed);
}
if (!parsed || typeof parsed !== 'object') {
  throw new Error('Classifier returned an unexpected shape: ' + JSON.stringify($json).slice(0, 300));
}

const category = parsed.category || 'Technical Question';
const priority = parsed.priority || 'Medium';
const confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 0;
const identifiers = Array.isArray(parsed.identifiers)
  ? parsed.identifiers.map((entry) => String(entry).trim()).filter(Boolean)
  : [];
const rawMessage = orig.raw_message || '';
const text = rawMessage.toLowerCase();

// ---------------------------------------------------------------------------
// Step 4 - Routing decision. Five categories map onto four standing queues,
// with General Triage as the fallback for anything unrecognised.
// ---------------------------------------------------------------------------
const queueMap = {
  'Bug Report': 'Engineering',
  'Incident/Outage': 'Engineering',
  'Feature Request': 'Product',
  'Billing Issue': 'Billing',
  'Technical Question': 'IT/Security',
};
let routing_queue = queueMap[category] || 'General Triage';

// ---------------------------------------------------------------------------
// Step 6 - Human escalation criteria. Every rule is deterministic and evaluated
// independently of the model's own priority judgement, so a misclassification
// cannot quietly bypass a hard business rule.
// ---------------------------------------------------------------------------
const reasons = [];

// (a) Low confidence - the fallback required by Step 4.
if (confidence < 0.7) reasons.push('Low confidence (<70%)');

// (b) Outage / incident signal.
if (category === 'Incident/Outage' ||
    /\boutage\b|\bdown for (all|multiple) users\b|\bmultiple users (are )?(affected|impacted)\b|\bproduction (is )?down\b/.test(text)) {
  reasons.push('Outage / incident signal');
}

// (c) Explicit critical wording, regardless of predicted category.
if (/\b(urgent|asap|critical|emergency|data loss|security breach|breach|locked out)\b/.test(text)) {
  reasons.push('Critical wording in message');
}

// (d) Billing error over $500. The amount scan runs on every message so a
// misclassified billing complaint still trips the rule; the context check stops
// it firing on an unrelated figure such as a pricing tier.
const amounts = (rawMessage.match(/\$\s?[\d,]+(?:\.\d+)?/g) || [])
  .map((a) => parseFloat(a.replace(/[$,\s]/g, '')))
  .filter((n) => !isNaN(n));
const maxAmt = amounts.length ? Math.max(...amounts) : 0;
const billingContext = category === 'Billing Issue' ||
  /invoice|charge|billed|billing|refund|payment|contract rate/.test(text);
if (maxAmt > 500 && billingContext) {
  reasons.push('Billing amount over $500 ($' + maxAmt + ')');
}

const escalation_flag = reasons.length > 0;
// Escalated records go to the human queue INSTEAD of the standard destination.
if (escalation_flag) routing_queue = 'Human Escalation';

// Step 5 - the structured record. One flat object, every field from steps 2-4
// plus the receiving-team summary.
return [{
  json: {
    source: orig.source || '',
    raw_message: rawMessage,
    category,
    priority,
    confidence,
    core_issue: parsed.core_issue || '',
    // Array here; the Data Table nodes join it for their string column.
    identifiers,
    urgency_signal: parsed.urgency_signal || '',
    routing_queue,
    escalation_flag,
    escalation_reason: reasons.join('; '),
    summary: parsed.summary || '',
    processed_at: new Date().toISOString(),
  },
}];
